#[repr(C)]
pub struct IhkRwSpinlock {
    counter: AtomicI32,
}

#[no_mangle]
pub unsafe extern "C" fn __ihk_rwspinlock_read_lock(lock: *mut IhkRwSpinlock) {
    loop {
        let desired = (*lock).counter.load(Ordering::SeqCst) & !IHK_RWSPINLOCK_WRITELOCKED;
        let new_val = desired + 1;

        if (new_val as u32) < IHK_RWSPINLOCK_WRITELOCKED as u32
            && (*lock)
                .counter
                .compare_exchange(desired, new_val, Ordering::SeqCst, Ordering::SeqCst)
                .is_ok()
        {
            return;
        }
        cpu_pause();
    }
}

#[no_mangle]
pub unsafe extern "C" fn __ihk_rwspinlock_read_unlock(lock: *mut IhkRwSpinlock) {
    let _ = (*lock).counter.fetch_sub(1, Ordering::SeqCst);
}

#[no_mangle]
pub unsafe extern "C" fn ihk_rwspinlock_read_lock_noirq(lock: *mut IhkRwSpinlock) {
    preempt_disable();
    __ihk_rwspinlock_read_lock(lock);
}

#[no_mangle]
pub unsafe extern "C" fn ihk_rwspinlock_read_unlock_noirq(lock: *mut IhkRwSpinlock) {
    __ihk_rwspinlock_read_unlock(lock);
    preempt_enable();
}

#[inline(always)]
unsafe fn vm_range_from_rb_node(node: *mut RbNode) -> *mut VmRange {
    node.cast::<VmRange>()
}

#[no_mangle]
pub extern "C" fn process_range_cache_hit_result(
    cache_start: CULong,
    cache_end: CULong,
    start: CULong,
    end: CULong,
) -> CInt {
    (cache_start <= start && cache_end >= end) as CInt
}

#[no_mangle]
pub extern "C" fn process_lookup_range_relation_result(
    start: CULong,
    end: CULong,
    range_start: CULong,
    range_end: CULong,
) -> CInt {
    if end <= range_start {
        -1
    } else if start >= range_end {
        1
    } else if start < range_start {
        -2
    } else {
        0
    }
}

#[no_mangle]
pub unsafe extern "C" fn process_range_cache_store_result(
    cache: *mut *mut c_void,
    count: CInt,
    indexp: *mut CInt,
    match_range: *mut c_void,
) -> CInt {
    if cache.is_null() || count <= 0 || indexp.is_null() || match_range.is_null() {
        return -EINVAL;
    }

    let new_index = unsafe { (*indexp - 1 + count) % count };
    unsafe {
        *indexp = new_index;
        *cache.add(new_index as usize) = match_range;
    }
    new_index
}

#[no_mangle]
pub unsafe extern "C" fn process_lookup_memory_range_body_result(
    vm: *mut ProcessVm,
    start: CULong,
    end: CULong,
) -> *mut VmRange {
    if vm.is_null() || end <= start {
        return null_mut();
    }

    let mut i = 0;
    let cache_base = (&raw mut (*vm).range_cache).cast::<*mut VmRange>();
    while i < crate::abi::VM_RANGE_CACHE_SIZE as CInt {
        let c_i = (i + (*vm).range_cache_ind) % crate::abi::VM_RANGE_CACHE_SIZE as CInt;
        let cached = *cache_base.add(c_i as usize);
        if !cached.is_null()
            && process_range_cache_hit_result((*cached).start, (*cached).end, start, end) != 0
        {
            return cached;
        }
        i += 1;
    }

    let mut node = (*vm).vm_range_tree.rb_node.cast::<RbNode>();
    let mut matched: *mut VmRange = null_mut();
    while !node.is_null() {
        let range = vm_range_from_rb_node(node);
        let relation =
            process_lookup_range_relation_result(start, end, (*range).start, (*range).end);
        if relation < -1 {
            matched = range;
            node = (*node).rb_left;
        } else if relation < 0 {
            node = (*node).rb_left;
        } else if relation > 0 {
            node = (*node).rb_right;
        } else {
            matched = range;
            break;
        }
    }

    if !matched.is_null() && end > (*matched).start {
        let cache = (&raw mut (*vm).range_cache).cast::<*mut c_void>();
        process_range_cache_store_result(
            cache,
            crate::abi::VM_RANGE_CACHE_SIZE as CInt,
            &raw mut (*vm).range_cache_ind,
            matched.cast(),
        );
    }

    matched
}

#[no_mangle]
pub unsafe extern "C" fn process_range_public_log_result(
    event: CInt,
    vm: *mut ProcessVm,
    range: *mut VmRange,
    start: CULong,
    end: CULong,
    error: CInt,
    log_fn: Option<ProcessRangePublicLogFn>,
) -> CInt {
    if let Some(log_fn) = log_fn {
        log_fn(event, vm.cast(), range, start, end, error);
    }
    0
}

#[no_mangle]
pub unsafe extern "C" fn process_lookup_memory_range_public_result(
    vm: *mut ProcessVm,
    start: CULong,
    end: CULong,
    log_fn: Option<ProcessRangePublicLogFn>,
) -> *mut VmRange {
    let _ = process_range_public_log_result(
        PROCESS_RANGE_PUBLIC_LOG_LOOKUP_ENTER,
        vm,
        null_mut(),
        start,
        end,
        0,
        log_fn,
    );
    let matched = process_lookup_memory_range_body_result(vm, start, end);
    let _ = process_range_public_log_result(
        PROCESS_RANGE_PUBLIC_LOG_LOOKUP_EXIT,
        vm,
        matched,
        start,
        end,
        0,
        log_fn,
    );
    matched
}

#[no_mangle]
pub unsafe extern "C" fn lookup_process_memory_range(
    vm: *mut ProcessVm,
    start: CULong,
    end: CULong,
) -> *mut VmRange {
    process_lookup_memory_range_public_result(vm, start, end, Some(process_range_public_log_bridge))
}

#[inline(always)]
unsafe fn read_char(ptr: *const i8) -> i8 {
    read_volatile(ptr)
}

#[inline(always)]
unsafe fn write_char(ptr: *mut i8, value: i8) {
    write_volatile(ptr, value);
}

#[inline(always)]
fn char_diff(left: i8, right: i8) -> CInt {
    left as CInt - right as CInt
}

#[no_mangle]
pub unsafe extern "C" fn strlen(mut ptr: *const i8) -> SizeT {
    let head = ptr;

    while read_char(ptr) != 0 {
        ptr = ptr.add(1);
    }

    ptr.offset_from(head) as SizeT
}

#[no_mangle]
pub unsafe extern "C" fn strcpy(mut dest: *mut i8, mut src: *const i8) -> *mut i8 {
    let head = dest;

    loop {
        let ch = read_char(src);
        write_char(dest, ch);
        dest = dest.add(1);
        src = src.add(1);
        if ch == 0 {
            break;
        }
    }

    head
}

#[no_mangle]
pub unsafe extern "C" fn strcmp(mut s1: *const i8, mut s2: *const i8) -> CInt {
    while read_char(s1) != 0 && read_char(s1) == read_char(s2) {
        s1 = s1.add(1);
        s2 = s2.add(1);
    }

    char_diff(read_char(s1), read_char(s2))
}

#[no_mangle]
pub unsafe extern "C" fn memset(s: *mut c_void, c: CInt, mut n: SizeT) -> *mut c_void {
    let mut ptr = s.cast::<u8>();
    let byte = c as u8;

    while n > 0 {
        write_volatile(ptr, byte);
        ptr = ptr.add(1);
        n -= 1;
    }

    s
}

#[inline(always)]
unsafe fn list_add(new: *mut AbiListHead, prev: *mut AbiListHead, next: *mut AbiListHead) {
    (*next).prev = new;
    (*new).next = next;
    (*new).prev = prev;
    (*prev).next = new;
}

#[inline(always)]
unsafe fn list_add_after(new: *mut AbiListHead, head: *mut AbiListHead) {
    list_add(new, head, (*head).next);
}

#[inline(always)]
unsafe fn init_list_head(head: *mut AbiListHead) {
    (*head).next = head;
    (*head).prev = head;
}

#[inline(always)]
unsafe fn pagealloc_track_hash(file: *mut i8, line: CInt) -> CInt {
    let len = if file.is_null() {
        0
    } else {
        strlen(file.cast_const()) as CInt
    };
    len.wrapping_add(line) & PAGEALLOC_TRACK_HASH_MASK
}

#[inline(always)]
unsafe fn pagealloc_addr_hash(ptr: *mut c_void) -> CInt {
    ((ptr as CULong) >> 5 & PAGEALLOC_TRACK_HASH_MASK as CULong) as CInt
}

#[inline(always)]
unsafe fn pagealloc_track_entry_alloc_count(entry: *mut PageallocTrackEntry) -> &'static AtomicI32 {
    AtomicI32::from_ptr(&raw mut (*entry).alloc_count.counter)
}

#[inline(always)]
unsafe fn pagealloc_track_entry_from_hash(node: *mut AbiListHead) -> *mut PageallocTrackEntry {
    node.cast::<u8>()
        .sub(offset_of!(PageallocTrackEntry, hash))
        .cast::<PageallocTrackEntry>()
}

#[inline(always)]
unsafe fn pagealloc_track_log(
    log_fn: Option<MemPageallocTrackLogFn>,
    event: CInt,
    ptr: *mut c_void,
    file: *mut i8,
    line: CInt,
    npages: CInt,
) {
    if let Some(log) = log_fn {
        log(event, ptr, file, line, npages);
    }
}

#[inline(always)]
unsafe fn pagealloc_entry_addr_list_lock(entry: *mut PageallocTrackEntry) -> CULong {
    (&raw mut (*entry).addr_list_lock) as CULong
}

#[inline(always)]
unsafe fn pagealloc_rehash_addr_entry(
    addr_entry: *mut PageallocTrackAddrEntry,
    addr_hash: *mut AbiListHead,
    addr_locks: *mut IhkSpinlock,
    lock: MemKmallocSpinLockFn,
    unlock: MemKmallocSpinUnlockFn,
) {
    let addr_hash_index = pagealloc_addr_hash((*addr_entry).addr);
    let addr_lock = addr_locks.add(addr_hash_index as usize);
    let irq_flags = lock(addr_lock as CULong);
    list_add_after(
        &raw mut (*addr_entry).hash,
        addr_hash.add(addr_hash_index as usize),
    );
    unlock(addr_lock as CULong, irq_flags);
}

#[no_mangle]
pub unsafe extern "C" fn pagealloc_track_find_entry_result(
    file: *mut i8,
    line: CInt,
    track_hash: *mut AbiListHead,
) -> *mut PageallocTrackEntry {
    if file.is_null() || track_hash.is_null() {
        return null_mut();
    }

    let hash = pagealloc_track_hash(file, line);
    let head = track_hash.add(hash as usize);
    let mut node = (*head).next;

    while node != head {
        let entry = pagealloc_track_entry_from_hash(node);
        if (*entry).line == line && strcmp((*entry).file, file) == 0 {
            return entry;
        }
        node = (*node).next;
    }

    null_mut()
}

#[no_mangle]
pub unsafe extern "C" fn pagealloc_track_alloc_result(
    npages: CInt,
    p2align: CInt,
    flag: CULong,
    node: CInt,
    is_user: CInt,
    virt_addr: CULong,
    file: *mut i8,
    line: CInt,
    memdebug: *mut i8,
    track_initialized: CInt,
    track_hash: *mut AbiListHead,
    track_locks: *mut IhkSpinlock,
    addr_hash: *mut AbiListHead,
    addr_locks: *mut IhkSpinlock,
    runcount: CInt,
    base_alloc_fn: Option<MemPageallocBaseAllocFn>,
    meta_alloc_fn: Option<MemPageallocMetaAllocFn>,
    meta_free_fn: Option<MemPageallocMetaFreeFn>,
    lock_fn: Option<MemKmallocSpinLockFn>,
    unlock_fn: Option<MemKmallocSpinUnlockFn>,
    spin_init_fn: Option<MemPageallocSpinInitFn>,
    log_fn: Option<MemPageallocTrackLogFn>,
) -> *mut c_void {
    let Some(base_alloc) = base_alloc_fn else {
        return null_mut();
    };

    let result = base_alloc(npages, p2align, flag, node, is_user, virt_addr);
    if memdebug.is_null() || track_initialized == 0 || result.is_null() {
        return result;
    }
    if file.is_null()
        || track_hash.is_null()
        || track_locks.is_null()
        || addr_hash.is_null()
        || addr_locks.is_null()
    {
        return result;
    }
    let (Some(meta_alloc), Some(meta_free), Some(lock), Some(unlock), Some(spin_init)) = (
        meta_alloc_fn,
        meta_free_fn,
        lock_fn,
        unlock_fn,
        spin_init_fn,
    ) else {
        return result;
    };

    let hash = pagealloc_track_hash(file, line);
    let track_lock = track_locks.add(hash as usize);
    let irq_flags = lock(track_lock as CULong);
    let mut entry = pagealloc_track_find_entry_result(file, line, track_hash);

    if entry.is_null() {
        entry = meta_alloc(size_of::<PageallocTrackEntry>() as CInt, IHK_MC_AP_NOWAIT)
            .cast::<PageallocTrackEntry>();
        if entry.is_null() {
            unlock(track_lock as CULong, irq_flags);
            pagealloc_track_log(
                log_fn,
                PAGEALLOC_TRACK_LOG_ENTRY_ALLOC_FAILED,
                result,
                file,
                line,
                npages,
            );
            return result;
        }

        (*entry).line = line;
        pagealloc_track_entry_alloc_count(entry).store(1, Ordering::Relaxed);
        spin_init(pagealloc_entry_addr_list_lock(entry));
        init_list_head(&raw mut (*entry).addr_list);

        let file_len = strlen(file.cast_const()) as CInt;
        (*entry).file = meta_alloc(file_len.wrapping_add(1), IHK_MC_AP_NOWAIT).cast::<i8>();
        if (*entry).file.is_null() {
            pagealloc_track_log(
                log_fn,
                PAGEALLOC_TRACK_LOG_FILE_ALLOC_FAILED,
                result,
                file,
                line,
                npages,
            );
            meta_free(entry.cast::<c_void>());
            unlock(track_lock as CULong, irq_flags);
            return result;
        }

        strcpy((*entry).file, file.cast_const());
        init_list_head(&raw mut (*entry).hash);
        list_add_after(&raw mut (*entry).hash, track_hash.add(hash as usize));
        pagealloc_track_log(
            log_fn,
            PAGEALLOC_TRACK_LOG_ENTRY_ADDED,
            result,
            file,
            line,
            npages,
        );
    } else {
        pagealloc_track_entry_alloc_count(entry).fetch_add(1, Ordering::Relaxed);
    }
    unlock(track_lock as CULong, irq_flags);

    let addr_entry = meta_alloc(
        size_of::<PageallocTrackAddrEntry>() as CInt,
        IHK_MC_AP_NOWAIT,
    )
    .cast::<PageallocTrackAddrEntry>();
    if addr_entry.is_null() {
        pagealloc_track_log(
            log_fn,
            PAGEALLOC_TRACK_LOG_ADDR_ALLOC_FAILED,
            result,
            file,
            line,
            npages,
        );
        return result;
    }

    (*addr_entry).addr = result;
    (*addr_entry).runcount = runcount;
    (*addr_entry).entry = entry;
    (*addr_entry).npages = npages;
    init_list_head(&raw mut (*addr_entry).list);
    init_list_head(&raw mut (*addr_entry).hash);

    let irq_flags = lock(pagealloc_entry_addr_list_lock(entry));
    list_add_after(&raw mut (*addr_entry).list, &raw mut (*entry).addr_list);
    unlock(pagealloc_entry_addr_list_lock(entry), irq_flags);

    pagealloc_rehash_addr_entry(addr_entry, addr_hash, addr_locks, lock, unlock);
    pagealloc_track_log(
        log_fn,
        PAGEALLOC_TRACK_LOG_ADDR_ADDED,
        result,
        file,
        line,
        npages,
    );

    result
}

#[inline(always)]
unsafe fn pagealloc_track_hash_ptr() -> *mut AbiListHead {
    (&raw mut PAGEALLOC_TRACK_HASH).cast::<AbiListHead>()
}

#[inline(always)]
unsafe fn pagealloc_track_locks_ptr() -> *mut IhkSpinlock {
    (&raw mut PAGEALLOC_TRACK_HASH_LOCKS).cast::<IhkSpinlock>()
}

#[inline(always)]
unsafe fn pagealloc_addr_hash_ptr() -> *mut AbiListHead {
    (&raw mut PAGEALLOC_ADDR_HASH).cast::<AbiListHead>()
}

#[inline(always)]
unsafe fn pagealloc_addr_locks_ptr() -> *mut IhkSpinlock {
    (&raw mut PAGEALLOC_ADDR_HASH_LOCKS).cast::<IhkSpinlock>()
}
